package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen5Test {

    @Test
    public void testToBoolean_Null() {
        assertFalse(BooleanUtils.toBoolean(null));
    }

    @Test
    public void testToBoolean_TrueInterned() {
        // Testing the 'str == "true"' optimization branch
        assertTrue(BooleanUtils.toBoolean("true"));
    }

    @Test
    public void testToBoolean_TrueNonInterned() {
        // Testing the 'case 4' branch with non-interned string
        assertTrue(BooleanUtils.toBoolean(new String("true")));
    }

    @Test
    public void testToBoolean_TrueVariations() {
        // Testing case 4: 't' variations
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("TrUe"));
        assertTrue(BooleanUtils.toBoolean("tRUE"));
        assertTrue(BooleanUtils.toBoolean("tRue"));

        // Testing case 4: 'T' variations
        assertTrue(BooleanUtils.toBoolean("True"));
        assertTrue(BooleanUtils.toBoolean("TRue"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("TRUE"));
    }

    @Test
    public void testToBoolean_OnVariations() {
        // Testing case 2: 'o' variations
        assertTrue(BooleanUtils.toBoolean("on"));
        assertTrue(BooleanUtils.toBoolean("oN"));
        assertTrue(BooleanUtils.toBoolean("On"));
        assertTrue(BooleanUtils.toBoolean("ON"));

        // Negative case length 2
        assertFalse(BooleanUtils.toBoolean("ox"));
        assertFalse(BooleanUtils.toBoolean("no"));
    }

    @Test
    public void testToBoolean_YesVariations() {
        // Testing case 3: 'y' variations
        assertTrue(BooleanUtils.toBoolean("yes"));
        assertTrue(BooleanUtils.toBoolean("yeS"));
        assertTrue(BooleanUtils.toBoolean("yEs"));
        assertTrue(BooleanUtils.toBoolean("yES"));

        // Testing case 3: 'Y' variations
        assertTrue(BooleanUtils.toBoolean("Yes"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
        assertTrue(BooleanUtils.toBoolean("YEs"));
        assertTrue(BooleanUtils.toBoolean("YES"));

        // Negative case length 3
        assertFalse(BooleanUtils.toBoolean("yan"));
        assertFalse(BooleanUtils.toBoolean("YESs")); // Check length logic
    }

    @Test
    public void testToBoolean_FalseAndOtherStrings() {
        // Length 5
        assertFalse(BooleanUtils.toBoolean("false"));
        // Length 4 but not true
        assertFalse(BooleanUtils.toBoolean("truk"));
        assertFalse(BooleanUtils.toBoolean("TRUEE")); // This actually hits case 5 (default false)
        assertFalse(BooleanUtils.toBoolean("fals"));
        // Length 1
        assertFalse(BooleanUtils.toBoolean("t"));
        // Length 0
        assertFalse(BooleanUtils.toBoolean(""));
        // Random string
        assertFalse(BooleanUtils.toBoolean("hello"));
    }

    @Test
    public void testToBoolean_EdgeCases() {
        // Testing case 4 logic branches for incorrect characters
        assertFalse(BooleanUtils.toBoolean("trxe"));
        assertFalse(BooleanUtils.toBoolean("truee")); // length 5 -> false
        assertFalse(BooleanUtils.toBoolean("tru"));  // length 3, not yes -> false

        // Testing case 3 logic branches for incorrect characters
        assertFalse(BooleanUtils.toBoolean("yea"));
        assertFalse(BooleanUtils.toBoolean("yee"));
        assertFalse(BooleanUtils.toBoolean("yxs"));

        // Testing case 2 logic branches for incorrect characters
        assertFalse(BooleanUtils.toBoolean("an"));
        assertFalse(BooleanUtils.toBoolean("onx")); // length 3 -> false
    }
}
